proc max_min_gcd {nums} {
# Find the greatest common divisor of the maximum and minimum numbers in 'nums'.
# >>> max_min_gcd {2 4 6 8 10}
# 2 (GCD of 2 and 10)
# >>> max_min_gcd {7 5 12 16 35}
# 5 (GCD of 5 and 35)

source_record.canonical_solution:
set max_num [lindex $nums 0]
set min_num [lindex $nums 0]
foreach num $nums {
if {$num > $max_num} {
set max_num $num
}
if {$num < $min_num} {
set min_num $num
}
}
return [gcd $max_num $min_num]
}

proc gcd {a b} {
# Helper function to find the greatest common divisor of two numbers.
while {$b != 0} {
set temp $b
set b [expr {$a % $b}]
set a $temp
}
return $a
}

