proc find_even_numbers {digits} {
# Find all unique even numbers formed by concatenating three digits from 'digits'.
# Exclude numbers with leading zeros.
# >>> find_even_numbers {1 2 3}
# {132 312}
# >>> find_even_numbers {0 1 2}
# {102 120 201 210}

source_record.canonical_solution:
set unique_numbers {}
set length [llength $digits]

for {set i 0} {$i < $length} {incr i} {
for {set j 0} {$j < $length} {incr j} {
for {set k 0} {$k < $length} {incr k} {
if {$i == $j || $j == $k || $i == $k} continue
set number [expr {[lindex $digits $i] * 100 + [lindex $digits $j] * 10 + [lindex $digits $k]}]
if {[lindex $digits $i] != 0 && $number % 2 == 0} {
lappend unique_numbers $number
}
}
}
}

return [lsort -integer -unique $unique_numbers]
}

